export function quickTrackSettings(id,options={}){const p=QUICK_TRACKS[id];if(!p)throw Error('Choose a Quick Track vibe.');const seed=options.seed??1,energy=options.energy??p.energy;if(!Number.isInteger(seed)||seed<0||seed>0xffffffff||!Number.isInteger(energy)||energy<0||energy>100)throw Error('Use a valid seed and energy from 0 to 100.');return{quickPreset:id,mood:p.scene,key:options.key??p.keyChoices[seed%p.keyChoices.length],scale:options.scale??p.scale,tempo:options.tempo??Math.round((p.tempo+(energy-p.energy)*.35)/2)*2,seed,energy,complexity:options.complexity??Math.round(25+energy*.45),adventure:options.adventure??8,introBars:options.introBars??p.introBars,verseBars:options.verseBars??p.verseBars,bridgeBars:options.bridgeBars??p.bridgeBars};}
